# Create PyTorch Dataset class
class SequenceDataset(Dataset):
    def __init__(self, sequences, targets):
        self.sequences = sequences
        self.targets = targets

    def __len__(self):
        return len(self.sequences)

    def __getitem__(self, idx):
        # Source: add EOS at the end
        src = np.concatenate([self.sequences[idx], [EOS_TOKEN]])

        # Target: add SOS at the beginning and EOS at the end
        tgt_input = np.concatenate([[SOS_TOKEN], self.targets[idx]])
        tgt_output = np.concatenate([self.targets[idx], [EOS_TOKEN]])

        return (
            torch.LongTensor(src),
            torch.LongTensor(tgt_input),
            torch.LongTensor(tgt_output)

# Implement Feedforward Network
class FeedForward(nn.Module):
    def __init__(self, d_model, d_ff, dropout=0.1):
        super(FeedForward, self).__init__()
        self.linear1 = nn.Linear(d_model, d_ff)
        self.linear2 = nn.Linear(d_ff, d_model)
        self.dropout = nn.Dropout(dropout)
        self.relu = nn.ReLU()

    def forward(self, x):
        return self.linear2(self.dropout(self.relu(self.linear1(x))))
